const file_path = '/home/user/.factory/missions/e194b9e3-6a67-42b9-bfc9-dd4e1ac23b0c/contract-work/board.md';
const src = await tools.Read({ file_path });
const parts = src.split(/(?=^### VAL-BOARD-)/m);
const preamble = parts.shift();
const blocks = parts.map(b => ({ id: parseInt(b.match(/^### VAL-BOARD-(\d{3})/)[1], 10), text: b.replace(/\s+$/, '') + '\n' }));
if (blocks.length !== 45) throw new Error(`expected 45 blocks, got ${blocks.length}`);
const replace = { 9: inputs.mergeA, 29: inputs.mergeB, 31: inputs.mergeC };
const drop = new Set([10, 30, 32]);
const mergedInto = { 10: 9, 30: 29, 32: 31 };
const kept = blocks.filter(b => !drop.has(b.id)).map(b => ({ id: b.id, text: replace[b.id] ? replace[b.id].replace(/\s+$/, '') + '\n' : b.text }));
const map = {};
kept.forEach((b, i) => { map[b.id] = i + 1; });
for (const [old, into] of Object.entries(mergedInto)) map[old] = map[into];
const pad = n => String(n).padStart(3, '0');
let out = preamble + kept.map(b => b.text.replace(/VAL-BOARD-(\d{3})/g, (m, d) => {
  const n = parseInt(d, 10);
  if (map[n] === undefined) throw new Error(`unmapped ref ${m}`);
  return `VAL-BOARD-${pad(map[n])}`;
})).join('\n');
await tools.Create({ file_path, content: out });
const check = await tools.Execute({ summary: 'Verify numbering and counts', command: `f="${file_path}"; echo "headings: $(grep -c '^### VAL-BOARD-' "$f") tools: $(grep -c '^Tool: ' "$f") evidence: $(grep -c '^Evidence: ' "$f")"; grep -o '^### VAL-BOARD-[0-9]*' "$f" | sed 's/.*-//' | awk 'NR!=$1+0 {print "out of sequence:", $1, "at position", NR}'; echo "refs:"; grep -o 'VAL-BOARD-[0-9]*' "$f" | sort | uniq -c | sort -k2 | awk '$1>1'; echo "tools used:"; grep '^Tool: ' "$f" | sort | uniq -c; head -1 "$f"`, riskLevel: 'low' });
text(check);

const file_path = '/home/user/.factory/missions/e194b9e3-6a67-42b9-bfc9-dd4e1ac23b0c/contract-work/board.md';
