const headings = r.filter(x => x.text.startsWith('### ')).map(x => `${x.line}: ${x.text}`);
const refs = r.filter(x => !x.text.startsWith('### ')).map(x => `${x.line}: ${x.text.match(/VAL-BOARD-\d{3}/g).join(', ')}`);
text('## headings\n' + headings.join('\n'));
text('## lines carrying cross-references\n' + refs.join('\n'));
